'AC-authority.1.1 AC-authority.2.1 AC-authority.3.1 AC-authority.4.1 EPIC-026'; from __future__ import annotations; import json; from pathlib import Path; from common.meta.extension import check_ac_tier_baseline as tier_gate; from common.meta.extension import generate_ac_registry as gar; from common.meta.extension.check_manifest import load_computed_concepts; ROOT = Path(__file__).resolve().parents[2]; MANIFEST = ROOT / 'common' / 'meta' / 'data' / 'MANIFEST.yaml'; FIRST_BATCH_EPICS = (3, 6, 21, 23)
def _write_epic(epic_dir: Path, fname: str, content: str) -> None: epic_dir.mkdir(parents=True, exist_ok=True); (epic_dir / fname).write_text(content, encoding='utf-8')
def test_AC26_1_1_ssot_defines_five_tiers_and_proof_matrix() -> None: 'AC-authority.1.1'; doc = (ROOT / 'common/meta/readme.md').read_text(encoding='utf-8'); concepts = load_computed_concepts(ROOT, MANIFEST); assert not (ROOT / 'docs/ssot/authority-tiers.md').exists(); assert gar.AC_TIERS == ('CODE-ONLY', 'CODE-LED', 'LLM-LED', 'LLM-ONLY', 'HU'); assert all((f'**{code}**' in doc for code in gar.AC_TIERS)); assert 'tier -> valid proof type' in doc; assert 'Cross-tier MUST rules' in doc; assert 'bit-level reproducible' in doc; assert 'evidence chain' in doc.lower(); assert 'golden' in doc.lower(); concept = concepts['authority_tiers']; assert concept['owner'] == 'common/meta/readme.md'
def test_AC26_2_1_tier_marker_flows_into_registry_value(tmp_path, monkeypatch) -> None: 'AC-authority.2.1'; epic_dir = tmp_path / 'docs' / 'project'; _write_epic(epic_dir, 'EPIC-003.statement-parsing.md', '| AC3.1.1 | Parse DBS PDF {tier:LLM-LED} | t | f | P0 | <!-- epic-owned: pending-package -->\n| AC3.1.2 | Parse CSV (DBS) {tier:CODE-ONLY} | t | f | P0 | <!-- epic-owned: pending-package -->\n| AC3.1.3 | No tier declared here | t | f | P0 | <!-- epic-owned: pending-package -->\n| AC3.1.4 | Bad tier {tier:ZZ} marker | t | f | P0 | <!-- epic-owned: pending-package -->\n'); monkeypatch.setattr(gar, 'EPIC_DIR', epic_dir); entries = gar.build_registry_entries(epic_source=epic_dir); assert entries['AC3.1.1']['tier'] == 'LLM-LED'; assert entries['AC3.1.2']['tier'] == 'CODE-ONLY'; assert '{tier' not in entries['AC3.1.1']['description']; assert entries['AC3.1.1']['description'] == 'Parse DBS PDF'; assert 'tier' not in entries['AC3.1.3']; assert 'tier' not in entries['AC3.1.4']
def test_AC26_3_1_tier_ratchet_is_shrink_only_and_blocks_new_debt(tmp_path) -> None: 'AC-authority.3.1'; baseline_path = tmp_path / 'ac-tier-baseline.json'; baseline = {'AC1.1.1'}; untagged_now = {'AC1.1.1', 'AC1.1.2'}; findings = tier_gate.evaluate(baseline, untagged_now); assert findings['new_untagged'] == ['AC1.1.2']; assert tier_gate.evaluate({'AC1.1.1', 'AC1.1.2'}, {'AC1.1.1'})['new_untagged'] == []; ratcheted = tier_gate.ratcheted_baseline({'AC1.1.1', 'AC1.1.3'}, {'AC1.1.1', 'AC9.9.9'}); assert ratcheted == {'AC1.1.1'}; tier_gate.write_baseline(baseline_path, {'AC2.1.1', 'AC10.1.1'}); payload = json.loads(baseline_path.read_text(encoding='utf-8')); assert payload['version'] == 1; assert payload['untagged'] == ['AC2.1.1', 'AC10.1.1']; assert tier_gate.load_baseline(baseline_path) == {'AC2.1.1', 'AC10.1.1'}
def test_AC26_4_1_first_batch_epics_fully_tagged_and_off_baseline() -> None:
    'AC-authority.4.1'; entries = gar.build_registry_entries(epic_source=ROOT / 'docs' / 'project'); baseline = tier_gate.load_baseline(ROOT / 'common/meta/data/ac-tier-baseline.json'); batch = {ac_id: entry for ac_id, entry in entries.items() if int(entry.get('epic', 0)) in FIRST_BATCH_EPICS}; assert batch, 'first-batch EPICs must contribute ACs'
    for (ac_id, entry) in batch.items(): assert entry.get('tier') in gar.AC_TIERS, f'{ac_id} has no valid tier'; assert ac_id not in baseline, f'{ac_id} is tagged but still in the debt baseline'
